function solve(accounts) {
  let groups = [];
  for (let idx = 0; idx < accounts.length; idx++) {
    const acc = accounts[idx];
    const emails = new Set(acc.slice(1));
    if (emails.size === 0) {
      groups.push({ name: acc[0], emails: new Set(), order: idx });
      continue;
    }
    const hits = [];
    for (const g of groups) {
      let overlap = false;
      for (const e of g.emails) {
        if (emails.has(e)) { overlap = true; break; }
      }
      if (overlap) hits.push(g);
    }
    if (hits.length === 0) {
      groups.push({ name: acc[0], emails: emails, order: idx });
      continue;
    }
    let best = hits[0];
    for (const g of hits) {
      if (g.order < best.order) best = g;
    }
    const merged = new Set(emails);
    for (const g of hits) {
      for (const e of g.emails) merged.add(e);
    }
    groups = groups.filter(g => hits.indexOf(g) === -1);
    groups.push({ name: best.name, emails: merged, order: best.order });
  }
  const cmp = (a, b) => {
    if (a[0] !== b[0]) return a[0] < b[0] ? -1 : 1;
    const m = Math.min(a.length, b.length);
    for (let i = 1; i < m; i++) {
      if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return a.length - b.length;
  };
  const out = groups.map(g => [g.name].concat(Array.from(g.emails).sort()));
  out.sort(cmp);
  return out;
}

function solve(accounts) {
  const parent = new Map();

  const find = (x) => {
    let root = x;
    while (parent.get(root) !== root) root = parent.get(root);
    while (parent.get(x) !== root) {
      const nxt = parent.get(x);
      parent.set(x, root);
      x = nxt;
    }
    return root;
  };

  const union = (a, b) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent.set(ra, rb);
  };

  for (const acc of accounts) {
    for (let i = 1; i < acc.length; i++) {
      if (!parent.has(acc[i])) parent.set(acc[i], acc[i]);
    }
    for (let i = 2; i < acc.length; i++) union(acc[1], acc[i]);
  }

  const groupName = new Map();
  for (const acc of accounts) {
    if (acc.length > 1) {
      const r = find(acc[1]);
      if (!groupName.has(r)) groupName.set(r, acc[0]);
    }
  }

  const buckets = new Map();
  for (const e of parent.keys()) {
    const r = find(e);
    if (!buckets.has(r)) buckets.set(r, []);
    buckets.get(r).push(e);
  }

  const cmp = (a, b) => {
    if (a[0] !== b[0]) return a[0] < b[0] ? -1 : 1;
    const m = Math.min(a.length, b.length);
    for (let i = 1; i < m; i++) {
      if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return a.length - b.length;
  };

  const out = [];
  for (const entry of buckets) out.push([groupName.get(entry[0])].concat(entry[1].sort()));
  for (const acc of accounts) {
    if (acc.length === 1) out.push([acc[0]]);
  }
  out.sort(cmp);
  return out;
}
